function fallbackPermissions(roleKey: AdminRoleKey): Set<string> {
  if (roleKey === "super_admin") return new Set(FALLBACK_PERMISSION_KEYS);
  return new Set(
    FALLBACK_PERMISSION_KEYS.filter((key) => !SUPER_ADMIN_ONLY_PERMISSIONS.includes(key)),
  );
}

/** Resolves the caller's effective permissions from the database. Falls back to
 * the legacy role mapping when migration 20261013000000 has not been applied, so
 * upgrading the function never locks every administrator out of their own console. */
export async function resolvePermissions(
  userId: string,
  roleKey: AdminRoleKey,
): Promise<Set<string>> {
  const { data, error } = await service().rpc("admin_effective_permissions", {
    p_user_id: userId,
  });
  if (error || !Array.isArray(data) || data.length === 0) {
    return fallbackPermissions(roleKey);
  }
  return new Set(data.filter((key): key is string => typeof key === "string"));
}

// ---------------------------------------------------------------------------
// Middleware
// ---------------------------------------------------------------------------

/** Route group that stays reachable while a password change is outstanding. */
const PASSWORD_CHANGE_ALLOWED = new Set([
  `${"/admin"}/me`,
  `${"/admin"}/credentials`,
  `${"/admin"}/profile`,
]);

const SESSION_TOUCH_INTERVAL_MS = 60_000;

export const requireAdmin = createMiddleware<AdminEnv>(async (c, next) => {
  const header = c.req.header("Authorization") ?? "";
  const headerToken = header.startsWith("Bearer ") ? header.slice(7).trim() : "";
  const cookieHeader = c.req.header("Cookie") ?? "";
  const cookieToken =
    cookieHeader
      .split(";")
      .map((part) => part.trim())
      .find((part) => part.startsWith(`${ADMIN_SESSION_COOKIE_NAME}=`))
      ?.slice(ADMIN_SESSION_COOKIE_NAME.length + 1) ?? "";
  const cookieOnly = !headerToken && Boolean(cookieToken);
  const token = headerToken || cookieToken;
  if (!token) return c.json({ error: "Sign in to continue." }, 401);

  // HttpOnly cookies can accompany cross-origin requests. Validate their Origin
  // explicitly to prevent a hostile site from using a browser's admin cookie.
  if (cookieOnly) {
    const origin = c.req.header("Origin");
    if (!origin || !ALLOWED_ORIGINS.includes(origin)) {
      return c.json({ error: "This administrator request is not allowed." }, 403);
    }
  }

  const db = service();
  const tokenHash = await sha256Hex(token);
  const { data: sessionRow } = await db
    .from("admin_sessions")
    .select("id,admin_user_id,expires_at,revoked_at,reauthenticated_at,last_seen_at")
    .eq("session_token_hash", tokenHash)
    .maybeSingle();
  const session = sessionRow as AdminSessionRow | null;
  if (!session) {
    return c.json({ error: "Your administrator session has expired. Sign in again." }, 401);
  }
  if (session.revoked_at) {
    return c.json(
      {
        error: "This administrator session was signed out.",
        code: "session_revoked",
      },
      401,
    );
  }
  if (new Date(session.expires_at).getTime() <= Date.now()) {
    return c.json(
      {
        error: "This administrator session has expired. Sign in again.",
        code: "session_expired",
      },
      401,
    );
  }

  const { data: userData, error: userError } = await db.auth.admin.getUserById(
    session.admin_user_id,
  );
  if (userError || !userData.user) {
    return c.json(
      {
        error: "Your administrator session has expired. Sign in again.",
      },
      401,
    );
  }
  const user = userData.user;

  const { data: profileRow } = await db
    .from("admin_profiles")
    .select("*")
    .eq("user_id", user.id)
    .maybeSingle();

  const profile = profileRow as AdminProfile | null;
  if (!profile || !profile.is_active) {
    return c.json({ error: "This account does not have administrator access." }, 403);
  }

  // The credential record for this administrator. When it exists, its `enabled`
  // flag is authoritative: disabling an account locks it out even if a stale
  // access token and session id are still presented.
  const { data: accountRow } = await db
    .from("admin_accounts")
    .select(
      "id,user_id,username,role_key,enabled,must_change_password,failed_attempts,locked_until,last_login_at",
    )
    .eq("user_id", user.id)
    .maybeSingle();
  const account = (accountRow as AdminAccountRow | null) ?? null;
  if (!account) {
    return c.json(
      {
        error: "This administrator account is not configured.",
        code: "account_missing",
      },
      403,
    );
  }
  if (!account.enabled) {
    return c.json(
      {
        error: "This administrator account is disabled.",
        code: "account_disabled",
      },
      403,
    );
  }
  if (account?.locked_until && new Date(account.locked_until).getTime() > Date.now()) {
    return c.json(
      {
        error: "This administrator account is temporarily locked. Try again shortly.",
        code: "account_locked",
      },
      403,
    );
  }

  const lastSeen = new Date(session.last_seen_at).getTime();
  if (Date.now() - lastSeen > SESSION_TOUCH_INTERVAL_MS) {
    await db
      .from("admin_sessions")
      .update({ last_seen_at: new Date().toISOString() })
      .eq("id", session.id);
  }

  const roleKey: AdminRoleKey =
    profile.role_key ?? (profile.role === "super_admin" ? "super_admin" : "admin");
  const permissions = await resolvePermissions(user.id, roleKey);

  // A forced password change blocks everything except the endpoints needed to
  // complete it. This is server-side, so clearing the flag in the browser does
  // nothing.
  if (profile.must_change_password && !PASSWORD_CHANGE_ALLOWED.has(c.req.path)) {
    return c.json(
      {
        error: "Choose a new administrator password before continuing.",
        code: "password_change_required",
      },
      428,
    );
  }

  c.set("admin", {
    user,
    profile,
    account,
    roleKey,
    permissions,
    session,
  });
  await next();
});

/** Server-side permission gate. The interface hides controls for usability, but
 * this is the enforcement point: a forged `isAdmin` boolean in the browser grants
 * nothing, because the handler still has to reach a route guarded by this. */
export function requirePermission(permission: string) {
  return createMiddleware<AdminEnv>(async (c, next) => {
    const principal = c.get("admin");
    if (!principal) {
      return c.json({ error: "Sign in to continue." }, 401);
    }
    if (principal.permissions.has(permission)) {
      await next();
      return;
    }
    const errorId = referenceId();
    await writeAudit(c.req.raw, {
      adminUserId: principal.user.id,
      action: "admin.permission.denied",
      targetType: "permission",
      targetId: permission,
      reason: "missing_permission",
      result: "denied",
      metadata: { path: c.req.path, role: principal.roleKey },
      errorId,
    });
    return c.json(
      {
        error: `Your role does not include the "${permission}" permission.`,
        code: "forbidden",
        permission,
        errorId,
      },
      403,
    );
  });
}

/** Requires a recent password re-entry before a high-risk action. The window is
 * read from platform_settings so an administrator can widen or tighten it. */
export async function requireRecentReauth(
  c: Ctx,
  fallbackMinutes: number,
): Promise<Response | null> {
  const session = c.get("admin").session;
  const reauthenticatedAt = session?.reauthenticated_at;
  if (!reauthenticatedAt) {
    return c.json(
      {
        error: "Confirm your password before this action.",
        code: "reauth_required",
      },
      428,
    );
  }
  const { data } = await service()
    .from("platform_settings")
    .select("require_admin_reauth_minutes")
    .eq("id", true)
    .maybeSingle();
  const configured = data?.require_admin_reauth_minutes;
  const minutes = typeof configured === "number" ? configured : fallbackMinutes;
  if (Date.now() - new Date(reauthenticatedAt).getTime() > minutes * 60_000) {
    return c.json(
      {
        error: "Confirm your password before this action.",
        code: "reauth_required",
      },
      428,
    );
  }
  return null;
}

export type ForgePlan = {
  sku: "PACK100" | "PREMIUM";
  label: string;
  description: string;
  currency: "inr" | "usd";
  amount: number;
  priceId: string;
  enabled: boolean;
};
export type ForgeOffer = { code: string; label: string; promotionId: string; enabled: boolean };
export type ForgeConfig = {
  version: 1;
  revision: string;
  aiGuidance: string;
  documentation: string;
  providerDailyCap: number;
  plans: ForgePlan[];
  offers: ForgeOffer[];
  subscriptionDraft: {
    label: string;
    inr: number;
    usd: number;
    monthlyRequests: number;
    priceId: string;
  };
};
export const defaultForgeConfig: ForgeConfig = {
  version: 1,
  revision: "initial",
  aiGuidance:
    "Use a calm, helpful VELORI voice. Build polished presentations, animations and interactive pages. Follow the latest request while preserving working features.",
  documentation:
    "VELORI Forge plans\n\nFree: local creation with VELORI attribution. Connected accounts receive the allowance reported by the server.\n\nCredit packs: one-time generation credits. Payment is confirmed by a verified webhook before credits are granted.\n\nPremium: current installed entitlement; provider capacity and fair-use controls always apply.\n\nRecurring Pro subscriptions are not active until the separate commercial database and settlement upgrade is approved, installed and tested.\n\nOffline source files remain editable. Hosted quotas cannot be enforced after an HTML file leaves VELORI.",
  providerDailyCap: 250,
  plans: [],
  offers: [],
  subscriptionDraft: {
    label: "Pro Monthly",
    inr: 99900,
    usd: 1200,
    monthlyRequests: 50000,
    priceId: "",
  },
};
const text = (v: unknown, max: number) => {
  if (typeof v !== "string" || v.length > max) throw Error("A text field exceeds its limit.");
  return v.trim();
};
const money = (v: unknown) => {
  if (!Number.isSafeInteger(v) || Number(v) < 1 || Number(v) > 100000000)
    throw Error("Use a positive price in minor currency units.");
  return Number(v);
};
export function parseForgeConfig(value: unknown): ForgeConfig {
  const v = value as ForgeConfig;
  if (
    !v ||
    v.version !== 1 ||
    !Array.isArray(v.plans) ||
    v.plans.length > 4 ||
    !Array.isArray(v.offers) ||
    v.offers.length > 10
  )
    throw Error("Invalid Forge configuration.");
  if (!Number.isInteger(v.providerDailyCap) || v.providerDailyCap < 1 || v.providerDailyCap > 10000)
    throw Error("Provider request cap must be 1–10,000.");
  const keys = new Set<string>(),
    codes = new Set<string>();
  const plans = v.plans.map((p) => {
    if (
      !p ||
      !["PACK100", "PREMIUM"].includes(p.sku) ||
      !["inr", "usd"].includes(p.currency) ||
      typeof p.enabled !== "boolean"
    )
      throw Error("Invalid plan.");
    const key = p.sku + ":" + p.currency;
    if (keys.has(key)) throw Error("A plan/currency occurs twice.");
    keys.add(key);
    const priceId = text(p.priceId, 100);
    if (priceId && !/^price_[A-Za-z0-9]+$/.test(priceId)) throw Error("Use a Stripe price ID.");
    if (p.enabled && !priceId) throw Error("Enabled plans require a verified price ID.");
    return {
      sku: p.sku,
      currency: p.currency,
      label: text(p.label, 80),
      description: text(p.description, 220),
      amount: money(p.amount),
      priceId,
      enabled: p.enabled,
    };
  });
  const offers = v.offers.map((o) => {
    const code = text(o.code, 30).toUpperCase();
    if (!/^[A-Z0-9_-]{3,30}$/.test(code) || codes.has(code))
      throw Error("Use unique coupon codes of 3–30 characters.");
    codes.add(code);
    const promotionId = text(o.promotionId, 100);
    if (!/^promo_[A-Za-z0-9]+$/.test(promotionId) || typeof o.enabled !== "boolean")
      throw Error("Coupons require a Stripe promotion code ID.");
    return { code, label: text(o.label, 100), promotionId, enabled: o.enabled };
  });
  const d = v.subscriptionDraft;
  if (
    !d ||
    !Number.isInteger(d.monthlyRequests) ||
    d.monthlyRequests < 1 ||
    d.monthlyRequests > 500000
  )
    throw Error("Invalid subscription request limit.");
  const priceId = text(d.priceId, 100);
  if (priceId && !/^price_[A-Za-z0-9]+$/.test(priceId)) throw Error("Use a subscription price ID.");
  return {
    version: 1,
    revision: text(v.revision, 80),
    aiGuidance: text(v.aiGuidance, 2000),
    documentation: text(v.documentation, 5000),
    providerDailyCap: v.providerDailyCap,
    plans,
    offers,
    subscriptionDraft: {
      label: text(d.label, 80),
      inr: money(d.inr),
      usd: money(d.usd),
      monthlyRequests: d.monthlyRequests,
      priceId,
    },
  };
}
export function readForgeConfig(env: (name: string) => string | undefined) {
  for (const key of ["VELORI_CUSTOM_FORGE_CONFIG", "VELORI_CUSTOM_FORGE_CONFIG_PREVIOUS"]) {
    try {
      const raw = env(key);
      if (raw) return parseForgeConfig(JSON.parse(raw));
    } catch {
      /* A malformed candidate must not replace the previous configuration. */
    }
  }
  return structuredClone(defaultForgeConfig);
}
